mapper.sql:
where true
  and s.created_at >= cast(#{from} as date)::timestamp at time zone #{zone}
  and s.created_at < (cast(#{to} as date) + 1)::timestamp at time zone #{zone}
  and s.item_id = #{itemId}

  and (s.serial_no like '%' || #{keyword} || '%' escape '\' or w.wo_no like '%' || #{keyword} || '%' escape '\')

mapper.select:
select 

 where s.wo_id = #{woId}
 order by s.serial_no

select 

 where p.serial_id = #{serialId}
 order by p.part_id
